css="""@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Noto+Sans+JP:wght@400;500;700;900&display=swap');
:root{--bg:#0e1110;--ink:#e9eddf;--muted:#8f998c;--line:#363c35;--accent:#ecff70;--panel:#181d19;color-scheme:dark}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:radial-gradient(ellipse at 80% 0,rgba(192,255,96,.06),transparent 35%),var(--bg);color:var(--ink);font-family:"Noto Sans JP",system-ui,sans-serif}
body:before{content:"";position:fixed;inset:0;pointer-events:none;background:linear-gradient(rgba(255,255,255,.03) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.03) 1px,transparent 1px);background-size:38px 38px;mask-image:linear-gradient(to bottom,#000,transparent 90%)}a{color:inherit;text-decoration:none}button,input,textarea,select{font:inherit}button{cursor:pointer}button:focus-visible,a:focus-visible,input:focus-visible,textarea:focus-visible{outline:3px solid var(--accent);outline-offset:3px}
.wrap{width:min(1200px,calc(100% - 40px));margin:auto;position:relative}.mono{font-family:"DM Mono",monospace;letter-spacing:.06em}.bar{border-bottom:1px solid var(--line)}.nav{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:19px 0;font-size:12px}.brand{font-size:13px;font-weight:900;letter-spacing:.1em}.brand i{font-style:normal;background:var(--accent);color:#151915;padding:3px 7px;margin-right:10px}
.hero{padding:78px 0 58px;display:grid;grid-template-columns:1.35fr 1fr;gap:36px;align-items:end}.eyebrow{font-size:12px;color:var(--accent);margin-bottom:18px}.hero h1{margin:0;line-height:1.07;font-size:clamp(48px,7.3vw,100px);letter-spacing:-.09em;font-weight:900}.hero h1 span{color:var(--accent)}.lead{max-width:430px;font-size:15px;line-height:2;color:#bcc5b8}.stat{display:flex;gap:28px;margin-top:29px}.stat b{font-size:34px;display:block}.stat small{color:var(--muted);font-size:11px}.marquee{border-block:1px solid var(--line);overflow:hidden;white-space:nowrap;color:#99a496;font:12px "DM Mono",monospace;padding:13px 0}.marquee span{display:inline-block;animation:marquee 34s linear infinite}@keyframes marquee{to{transform:translateX(-50%)}}
.gallery-head{padding:44px 0 24px;display:flex;justify-content:space-between;align-items:end;gap:20px}.gallery-head h2{font-size:clamp(25px,4vw,42px);margin:0}.search{background:#1c221e;border:1px solid #51594f;border-radius:0;color:#fff;width:min(300px,100%);padding:12px 15px}.chips{display:flex;flex-wrap:wrap;gap:7px;margin-bottom:24px}.chip{background:transparent;border:1px solid var(--line);color:#a7b1a4;padding:8px 12px;font-size:12px}.chip.active,.chip:hover{color:#11150f;background:var(--accent);border-color:var(--accent)}
.cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.card{min-height:222px;display:flex;flex-direction:column;justify-content:space-between;background:var(--panel);border:1px solid #323b33;padding:23px;position:relative;overflow:hidden;transition:border .2s,transform .2s}.card:hover{border-color:var(--accent);transform:translateY(-4px)}.card:after{content:"";position:absolute;right:-45px;top:-45px;width:140px;height:140px;border:1px solid var(--item);opacity:.15;transform:rotate(45deg)}.card-meta{display:flex;justify-content:space-between;color:var(--muted);font-size:11px}.card h3{font-size:21px;letter-spacing:-.04em;margin:24px 0 10px}.card p{color:#9da79a;line-height:1.65;font-size:12px;margin:0}.card-bottom{display:flex;justify-content:space-between;align-items:end;margin-top:20px}.card-tag{color:var(--item);font-size:10px}.card-arrow{color:var(--item);font:24px "DM Mono",monospace}.footer{border-top:1px solid var(--line);margin-top:75px;padding:35px 0 55px;display:flex;justify-content:space-between;gap:20px;color:#8e9a8b;font-size:12px}
.work-head{padding:60px 0 32px}.back{color:var(--accent);font-size:12px}.work-no{margin-top:34px;color:var(--muted);font-size:12px}.work-head h1{font-size:clamp(34px,6vw,66px);letter-spacing:-.065em;margin:14px 0 10px}.work-head p{color:#adb7a8;line-height:1.75}.stage{min-height:420px;background:linear-gradient(145deg,#1b231d,#101512);border:1px solid #445346;position:relative;overflow:hidden;padding:32px;display:flex;flex-direction:column;justify-content:center;align-items:center;gap:18px;text-align:center}.stage::before{position:absolute;content:"EXPERIMENT // RUNNING";font:10px "DM Mono",monospace;letter-spacing:.1em;top:17px;left:19px;color:#7d8c7e}.stage::after{position:absolute;content:"NO PRACTICAL VALUE";font:10px "DM Mono",monospace;bottom:17px;right:19px;color:#657466}
.stage h2{font-size:clamp(25px,5vw,48px);letter-spacing:-.065em;margin:0}.stage p{margin:0;color:#b1c0af}.big{font:clamp(56px,11vw,125px) "DM Mono",monospace;line-height:1.1;letter-spacing:-.06em;color:var(--accent)}.action{background:var(--accent);border:2px solid var(--accent);color:#131a12;padding:13px 22px;font-weight:900;min-height:48px;transition:transform .1s}.action:hover{filter:brightness(1.07)}.alt{background:transparent;color:var(--ink);border:1px solid #667465}.terminal{font:13px/1.8 "DM Mono",monospace;background:#0c120c;border:1px solid #3d5240;color:var(--accent);padding:15px;text-align:left;max-width:100%;white-space:pre-wrap;overflow-wrap:anywhere}.input{padding:12px;background:#0e1710;color:var(--ink);border:1px solid #60715f;width:min(450px,100%)}.meter{width:min(470px,100%);height:22px;border:1px solid #697b6c;overflow:hidden;text-align:left}.fill{height:100%;width:0%;background:var(--accent);transition:width .3s}.stage .hstack{display:flex;gap:9px;flex-wrap:wrap;justify-content:center}.sub{font-size:12px;color:#889b89}.work-nav{display:flex;gap:10px;justify-content:space-between;margin-top:24px}.work-nav a{border:1px solid var(--line);padding:14px 16px;min-width:45%;font-size:12px}.work-nav a:hover{border-color:var(--accent)}.footnote{color:#899489;line-height:1.8;font-size:12px;margin-top:20px}.grid-bars{display:flex;align-items:end;gap:10px;height:170px;width:min(400px,100%);border-bottom:1px solid #6b786b}.grid-bars i{display:block;flex:1;background:var(--accent);opacity:.75;transition:height .5s}.plant{font-size:110px}.fade{animation:blink .75s steps(2) infinite}@keyframes blink{50%{opacity:.2}}
#stage button{max-width:100%}@media(max-width:800px){.hero{grid-template-columns:1fr;padding:55px 0 35px}.cards{grid-template-columns:repeat(2,minmax(0,1fr))}.gallery-head{align-items:stretch;flex-direction:column}.search{width:100%}.stage{min-height:390px;padding:24px}}@media(max-width:550px){.cards{grid-template-columns:1fr}.nav .mono{display:none}.footer{flex-direction:column}.work-nav a{min-width:0;flex:1}.stat b{font-size:28px}}@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation-duration:.01ms!important;transition-duration:.01ms!important;scroll-behavior:auto!important}}
"""
